WITH valid_accounts AS (SELECT * FROM accounts WHERE balance > 34000 OR customer_id = 30), summary AS (SELECT customer_id, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, COUNT(balance) AS balance_count, COUNT(*) AS total_count FROM valid_accounts GROUP BY customer_id, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT customer_id, opened_cohort, balance_count, total_count FROM summary ORDER BY balance_count DESC;
